export interface Env {
  OAUTH_KV: KVNamespace;
  /** The Vault Durable Object: secrets, approvals, machines, audit, settings. */
  VAULT: DurableObjectNamespace;
  /** R2 bucket for nightly encrypted backups. */
  BACKUPS: R2Bucket;
  /** Public origin of this Worker, e.g. https://secret-broker.example.workers.dev */
  PUBLIC_URL?: string;

  GITHUB_CLIENT_ID: string;
  GITHUB_CLIENT_SECRET: string;
  COOKIE_ENCRYPTION_KEY: string;
  /** Comma-separated numeric GitHub user ids. Empty means nobody. */
  ALLOWED_GITHUB_IDS: string;

  /** base64 32 bytes. Generated by `npm run setup-keys`; copy kept in your recovery kit. */
  VAULT_MASTER_KEY: string;
  /** Only during a master key rotation: the old key, so existing data can be re-wrapped. */
  VAULT_MASTER_KEY_PREVIOUS?: string;
  /** PEM SPKI. Backups are encrypted to this; the private key stays offline in your recovery kit. */
  BACKUP_PUBLIC_KEY: string;
}

/** Stored inside each issued MCP token. Deliberately holds no credentials. */
export interface Props extends Record<string, unknown> {
  githubId: string;
  login: string;
}

/** Numeric GitHub ids from ALLOWED_GITHUB_IDS; anything that is not all digits is ignored. */
export function allowedIds(env: Pick<Env, 'ALLOWED_GITHUB_IDS'>): string[] {
  return (env.ALLOWED_GITHUB_IDS ?? '')
    .split(',')
    .map((s) => s.trim())
    .filter((s) => /^\d+$/.test(s));
}

export function isAllowedUser(env: Pick<Env, 'ALLOWED_GITHUB_IDS'>, githubId: string): boolean {
  return allowedIds(env).includes(githubId);
}

/** COOKIE_ENCRYPTION_KEY signs sessions, CSRF tokens, approved-client cookies and deploy plans, so a short one is refused. */
export function sessionKeyProblem(key: string | undefined): string | null {
  return key && key.length >= 32
    ? null
    : 'COOKIE_ENCRYPTION_KEY is missing or too short; it needs at least 32 characters. Generate one with `openssl rand -hex 32`, then run `npx wrangler secret put COOKIE_ENCRYPTION_KEY`.';
}

/** Throws when the signing key is unusable, so no primitive ever signs with a weak key. */
export function assertSessionKey(key: string | undefined): void {
  const problem = sessionKeyProblem(key);
  if (problem) throw new Error(problem);
}

/**
 * Decision for the provider's clientRegistrationCallback, which runs after the provider has
 * validated the metadata and before it stores the client. Redirect hosts are checked first;
 * `take` then spends one slot of the registration window. Returns nothing to allow. A refusal
 * writes nothing.
 */
export async function registrationDecision(
  meta: Record<string, unknown>,
  take: (info: { name: string; hosts: string[] }) => Promise<boolean>,
): Promise<{ code: string; description: string; status: number } | undefined> {
  const uris = Array.isArray(meta.redirect_uris) ? meta.redirect_uris : [];
  if (uris.length === 0 || !uris.every(redirectAllowed)) {
    return { code: 'invalid_redirect_uri', description: 'redirect_uri host is not allowed', status: 400 };
  }
  const hosts = [...new Set(uris.map((u) => new URL(String(u)).hostname))];
  if (await take({ name: typeof meta.client_name === 'string' ? meta.client_name : '', hosts })) return undefined;
  console.log(JSON.stringify({ event: 'register_refused', hosts: hosts.slice(0, 10) }));
  return { code: 'access_denied', description: 'Client registration is closed. Open it from the vault dashboard under Connectors, then try again.', status: 403 };
}

/** OAuth redirect targets a dynamically registered client may use: Claude's own callbacks and loopback for local clients. */
const REDIRECT_HOSTS = ['claude.ai', 'claude.com', 'anthropic.com'];

export function redirectAllowed(uri: unknown): boolean {
  try {
    const u = new URL(String(uri));
    if (u.hostname === 'localhost' || u.hostname === '127.0.0.1' || u.hostname === '[::1]') return u.protocol === 'http:' || u.protocol === 'https:';
    return u.protocol === 'https:' && REDIRECT_HOSTS.some((h) => u.hostname === h || u.hostname.endsWith(`.${h}`));
  } catch {
    return false;
  }
}
